import{_ as t,a as r,b as i}from"./chunks/bubbles-03.CRJ58gUA.js";import{_ as e,o as n,c as o,a3 as s}from"./chunks/framework.D1iekJsc.js";const f=JSON.parse('{"title":"吹き出しと入力欄","description":"MiniTavern の吹き出しと入力欄。テーマに従うか、背景、角丸、地の文・動作・セリフの色、ぼかしを個別に変えます。","frontmatter":{"title":"吹き出しと入力欄","description":"MiniTavern の吹き出しと入力欄。テーマに従うか、背景、角丸、地の文・動作・セリフの色、ぼかしを個別に変えます。","head":[["meta",{"name":"keywords","content":"酒場,AI酒場,MiniTavern,AI相棒,AI友達,AIローカルチャット,Silly Tavern,SillyTavern,スマホでSilly Tavern,Silly Tavernスマホ版,Silly Tavern Android,Silly Tavern iOS,AIロールプレイ,キャラクターカード,AIチャット,スマホAI,オフラインAI,AIストーリー,ローカルLLM,Ollama,LM Studio,ワールドブック,正規表現,BYOK,ユーザーガイド,マニュアル"}],["meta",{"property":"og:title","content":"吹き出しと入力欄 · MiniTavern Docs"}],["meta",{"property":"og:description","content":"MiniTavern の吹き出しと入力欄。テーマに従うか、背景、角丸、地の文・動作・セリフの色、ぼかしを個別に変えます。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/ja/manual/bubbles"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/ja/manual/bubbles"}]]},"headers":[],"relativePath":"ja/manual/bubbles.md","filePath":"ja/manual/bubbles.md","lastUpdated":1791862671000}'),l={name:"ja/manual/bubbles.md"};function g(c,a,p,d,u,h){return n(),o("div",null,[...a[0]||(a[0]=[s('<h1 id="吹き出しと入力欄" tabindex="-1">吹き出しと入力欄 <a class="header-anchor" href="#吹き出しと入力欄" aria-label="Permalink to &quot;吹き出しと入力欄&quot;">​</a></h1><p>経路：下部 <strong>設定</strong> → <strong>チャット設定</strong> → <strong>吹き出しと入力欄</strong>。</p><p>ここで変えるのはアプリ全体のチャット見た目です。テーマと文字サイズは <strong>設定 → テーマとフォント</strong> のままです。</p><h2 id="手順" tabindex="-1">手順 <a class="header-anchor" href="#手順" aria-label="Permalink to &quot;手順&quot;">​</a></h2><div class="shot-flow"><figure class="shot-step"><img src="'+t+'" alt="設定ホーム"><figcaption>1 · 設定 → チャット設定</figcaption></figure><figure class="shot-step"><img src="'+r+'" alt="チャット設定の吹き出しと入力欄"><figcaption>2 · 吹き出しと入力欄</figcaption></figure><figure class="shot-step"><img src="'+i+'" alt="吹き出しの色と角丸"><figcaption>3 · テーマに従うをオフにして編集</figcaption></figure></div><h2 id="吹き出し" tabindex="-1">吹き出し <a class="header-anchor" href="#吹き出し" aria-label="Permalink to &quot;吹き出し&quot;">​</a></h2><p><strong>吹き出し</strong>と <strong>入力欄</strong> には、それぞれ <strong>テーマに従う</strong> があります。オンのときは現在のテーマです。オフにすると下の設定がテーマより優先され、空の色はテーマのままです。</p><ol><li><strong>AIの吹き出し</strong> と <strong>自分の吹き出し</strong>：色相環です。プリセット色は円で、選ぶとチェックが付きます。不透明度と色の値を変えられ、値はコピーできます。行に「テーマの色を使う」と出ている項目は、まだテーマに従います。</li><li><strong>角丸</strong>：数値が大きいほど丸くなります。ドラッグしたあとは、テーマの間隔ではなくこの数値を使います。</li><li>文字色は分かれています。 <ul><li><strong>地の文</strong> とその背景：普通の本文と太字</li><li><strong>動作</strong>：<code>*アスタリスク*</code> で囲んだ文字</li><li><strong>セリフ</strong>：引用符の中</li><li>内心</li></ul></li><li>カードがこの記号を使っていなくても文字は表示され、地の文のスタイルになります。HTML カード全体は自分の色を使います。</li></ol><h2 id="入力欄" tabindex="-1">入力欄 <a class="header-anchor" href="#入力欄" aria-label="Permalink to &quot;入力欄&quot;">​</a></h2><p>入力欄側の <strong>テーマに従う</strong> をオフにすると、背景、角丸、プレースホルダ、文字色、ボタンアイコン、<strong>ぼかし</strong> を変えられます。</p><p>ぼかしをオンにすると色調と強さを調整できます。API 31 未満の Android にはこのスイッチがありません。iOS ではテーマに従うをオフにしたあと、ぼかしは初期状態でオンです。</p><h2 id="プレビュー" tabindex="-1">プレビュー <a class="header-anchor" href="#プレビュー" aria-label="Permalink to &quot;プレビュー&quot;">​</a></h2><p>右上の <strong>プレビュー</strong> はサンプルを開きます。背景は現在の言語の女性サンプルカードで、サンプル対話と入力欄があります。最後は AI のメッセージで、続行やスマート返信のボタンがありますが、押しても送信されません。入力欄も送信できません。左のボタンと設定も押せません。</p><h2 id="関連" tabindex="-1">関連 <a class="header-anchor" href="#関連" aria-label="Permalink to &quot;関連&quot;">​</a></h2><ul><li><a href="./chat">チャット</a>：吹き出しメニューと、そのチャットの設定</li><li><a href="./settings">設定</a>：テーマとフォント</li></ul>',15)])])}const _=e(l,[["render",g]]);export{f as __pageData,_ as default};
